WITH matched_keys AS (SELECT order_id, id FROM shipments INTERSECT ALL SELECT order_id, id FROM shipments WHERE delivered_date <= '2023-03-01'), reconciled AS (SELECT s.* FROM shipments s JOIN matched_keys k ON s.order_id = k.order_id AND s.id = k.id) SELECT CASE WHEN cost >= 83 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, COUNT_IF(carrier = 'Kerry') AS kerry_events, APPROX_PERCENTILE(cost, 0.5) AS cost_p50, PERCENTILE_APPROX(cost, 0.95) AS cost_p95, SUM(cost) FILTER (WHERE carrier = 'FedEx') AS fedex_total_cost FROM reconciled GROUP BY cost_tier HAVING cost_p95 > 0
